const folder = "<방>/home/일감/받은자료";

async function main() {
  const listed = await t5.call("local.file", { action: "list", path: folder, limit: 100 });

  const candidates = listed.result.items.filter(item => item.name.endsWith(".csv"));

  const matches = [];

  for (const file of candidates) {
    const fullPath = `${folder}/${file.name}`;
    const read = await t5.call("local.file", { action: "read", path: fullPath, limit: 2000 });
    if (read.result.text.includes("취소")) {
      matches.push(file.name);
    }
  }

  console.log({ matches });
}

main();
